import type { Html } from "foldkit/html";
import { html } from "foldkit/html";

import {
  avatarBadgeClasses,
  avatarClassesBySize,
  avatarFallbackClasses,
  avatarGroupClasses,
  avatarGroupCountClasses,
  avatarImageClasses,
} from "./view";
import type { AvatarSize } from "./view";

export type { AvatarSize };

export {
  avatarBaseClasses,
  avatarBadgeClasses,
  avatarClassesBySize,
  avatarFallbackClasses,
  avatarGroupClasses,
  avatarGroupCountClasses,
  avatarImageClasses,
  avatarSizeClassesBySize,
} from "./view";

export type AvatarStyle = Readonly<Record<string, string>>;

export type RootViewConfig = Readonly<{
  children: readonly Html[];
  size?: AvatarSize | undefined;
  classes?: string | undefined;
  style?: AvatarStyle | undefined;
}>;

export type ImageViewConfig = Readonly<{
  src: string;
  alt: string;
  classes?: string | undefined;
  style?: AvatarStyle | undefined;
}>;

export type FallbackViewConfig = Readonly<{
  children: readonly Html[];
  ariaLabel?: string | undefined;
  classes?: string | undefined;
  style?: AvatarStyle | undefined;
}>;

export type ViewConfig = Readonly<{
  fallback: string;
  src?: string | undefined;
  alt?: string | undefined;
  size?: AvatarSize | undefined;
  classes?: string | undefined;
  style?: AvatarStyle | undefined;
}>;

export type CountConfig = Readonly<{
  count: number;
  label?: string | undefined;
  classes?: string | undefined;
  style?: AvatarStyle | undefined;
}>;

export type BadgeViewConfig = Readonly<{
  children?: readonly Html[] | undefined;
  label?: string | undefined;
  classes?: string | undefined;
  style?: AvatarStyle | undefined;
}>;

const cn = (base: string, classes?: string): string =>
  [base, classes]
    .filter((value): value is string => value !== undefined && value !== "")
    .join(" ");

export const rootView = <ParentMessage>({
  children,
  size = "Default",
  classes,
  style,
}: RootViewConfig): Html => {
  const h = html<ParentMessage>();

  return h.span(
    [
      h.Attribute("data-slot", "avatar"),
      h.Attribute(
        "data-size",
        size === "Small" ? "sm" : size === "Large" ? "lg" : "default"
      ),
      ...(style === undefined ? [] : [h.Style(style)]),
      h.Class(cn(avatarClassesBySize(size), classes)),
    ],
    children
  );
};

export const imageView = <ParentMessage>({
  src,
  alt,
  classes,
  style,
}: ImageViewConfig): Html => {
  const h = html<ParentMessage>();

  return h.img([
    h.Attribute("data-slot", "avatar-image"),
    h.Src(src),
    h.Alt(alt),
    ...(style === undefined ? [] : [h.Style(style)]),
    h.Class(cn(avatarImageClasses, classes)),
  ]);
};

export const fallbackView = <ParentMessage>({
  children,
  ariaLabel,
  classes,
  style,
}: FallbackViewConfig): Html => {
  const h = html<ParentMessage>();

  return h.span(
    [
      h.Attribute("data-slot", "avatar-fallback"),
      ...(ariaLabel === undefined ? [] : [h.AriaLabel(ariaLabel)]),
      ...(style === undefined ? [] : [h.Style(style)]),
      h.Class(cn(avatarFallbackClasses, classes)),
    ],
    children
  );
};

export const view = <ParentMessage>({
  fallback,
  src,
  alt,
  size = "Default",
  classes,
  style,
}: ViewConfig): Html =>
  rootView<ParentMessage>({
    size,
    classes,
    style,
    children:
      src === undefined
        ? [
            fallbackView<ParentMessage>({
              children: [html<ParentMessage>().span([], [fallback])],
            }),
          ]
        : [imageView<ParentMessage>({ src, alt: alt ?? fallback })],
  });

export const badgeView = <ParentMessage>({
  children = [],
  label,
  classes,
  style,
}: BadgeViewConfig): Html => {
  const h = html<ParentMessage>();

  return h.span(
    [
      h.Attribute("data-slot", "avatar-badge"),
      ...(label === undefined ? [h.AriaHidden(true)] : [h.AriaLabel(label)]),
      ...(style === undefined ? [] : [h.Style(style)]),
      h.Class(cn(avatarBadgeClasses, classes)),
    ],
    children
  );
};

export const groupView = <ParentMessage>(
  children: readonly Html[],
  classes?: string
): Html => {
  const h = html<ParentMessage>();

  return h.div(
    [
      h.Attribute("data-slot", "avatar-group"),
      h.Class(cn(avatarGroupClasses, classes)),
    ],
    children
  );
};

export const countView = <ParentMessage>({
  count,
  label,
  classes,
  style,
}: CountConfig): Html => {
  const h = html<ParentMessage>();

  return h.span(
    [
      h.Attribute("data-slot", "avatar-group-count"),
      h.Class(cn(avatarGroupCountClasses, classes)),
      h.AriaLabel(label ?? `${count} more people`),
      h.Attribute("role", "img"),
      ...(style === undefined ? [] : [h.Style(style)]),
    ],
    [`+${count}`]
  );
};

export type AvatarSize = "Small" | "Default" | "Large";

export const avatarBaseClasses =
  "relative flex shrink-0 items-center justify-center overflow-hidden rounded-full bg-muted text-muted-foreground ring-2 ring-background";

export const avatarImageClasses = "h-full w-full rounded-full object-cover";

export const avatarFallbackClasses =
  "flex h-full w-full items-center justify-center rounded-full bg-muted text-sm font-medium";

export const avatarBadgeClasses =
  "absolute right-0 bottom-0 flex size-2.5 items-center justify-center rounded-full bg-green-600 text-[8px] text-white ring-2 ring-background dark:bg-green-800 [&>svg]:size-3";

export const avatarGroupClasses =
  "group/avatar-group flex -space-x-2 *:data-[slot=avatar]:ring-2 *:data-[slot=avatar]:ring-background";

export const avatarGroupCountClasses =
  "relative flex size-8 shrink-0 items-center justify-center rounded-full bg-muted text-sm text-muted-foreground ring-2 ring-background group-has-data-[size=lg]/avatar-group:size-10 group-has-data-[size=sm]/avatar-group:size-6 [&>svg]:size-4 group-has-data-[size=lg]/avatar-group:[&>svg]:size-5 group-has-data-[size=sm]/avatar-group:[&>svg]:size-3";

export const avatarSizeClassesBySize = (
  size: AvatarSize = "Default"
): string => {
  if (size === "Small") {
    return "size-6 text-xs";
  }

  if (size === "Large") {
    return "size-10 text-base";
  }

  return "size-8 text-sm";
};

export const avatarClassesBySize = (size: AvatarSize = "Default"): string =>
  `${avatarBaseClasses} ${avatarSizeClassesBySize(size)}`;

import { Scene } from "foldkit";
import type { Html } from "foldkit/html";
import { html } from "foldkit/html";
import { describe, test } from "vitest";

import * as Avatar from "./index";

const imageSrc =
  "data:image/svg+xml,%3Csvg xmlns='http://www.w3.org/2000/svg' viewBox='0 0 80 80'%3E%3Crect width='80' height='80' fill='%234f46e5'/%3E%3Ctext x='40' y='48' text-anchor='middle' font-size='24' font-family='Arial' fill='white'%3EAL%3C/text%3E%3C/svg%3E";

const view = (): Html => {
  const h = html<never>();

  return h.div(
    [h.Class("space-y-4")],
    [
      Avatar.view({ fallback: "AL", src: imageSrc, alt: "Ada Lovelace" }),
      Avatar.view({ fallback: "GH", size: "Large" }),
      Avatar.rootView({
        children: [Avatar.fallbackView({ children: [h.span([], ["LT"])] })],
      }),
      Avatar.rootView({
        children: [
          Avatar.fallbackView({ children: [h.span([], ["CN"])] }),
          Avatar.badgeView({ label: "Online" }),
        ],
      }),
      Avatar.groupView([
        Avatar.view({ fallback: "AL", src: imageSrc, alt: "Ada Lovelace" }),
        Avatar.view({ fallback: "GH" }),
        Avatar.countView({ count: 3 }),
      ]),
    ]
  );
};

describe("Avatar registry view", () => {
  test("renders image, fallback, group, and count affordances", () => {
    Scene.scene(
      {
        update: (model: undefined): readonly [undefined, []] => [model, []],
        view,
      },
      Scene.with(undefined),
      Scene.expect(Scene.role("img", { name: "Ada Lovelace" })).toExist(),
      Scene.expect(Scene.text("GH")).toExist(),
      Scene.expect(Scene.text("LT")).toExist(),
      Scene.expect(Scene.label("Online")).toExist(),
      Scene.expect(Scene.role("img", { name: "3 more people" })).toExist()
    );
  });
});
